WITH store_agg AS ( SELECT i.i_category, i.i_brand, ss.ss_sold_date_sk AS date_sk, SUM(ss.ss_ext_sales_price) AS store_sales_rev, SUM(ss.ss_net_profit) AS store_net_profit FROM store_sales ss JOIN item i ON ss.ss_item_sk = i.i_item_sk WHERE ss.ss_sold_date_sk BETWEEN 2450900 AND 2451100 GROUP BY i.i_category, i.i_brand, ss.ss_sold_date_sk ), web_agg AS ( SELECT i.i_category, i.i_brand, ws.ws_sold_date_sk AS date_sk, SUM(ws.ws_ext_sales_price) AS web_sales_rev, SUM(ws.ws_net_profit) AS web_net_profit FROM web_sales ws JOIN item i ON ws.ws_item_sk = i.i_item_sk WHERE ws.ws_sold_date_sk BETWEEN 2450900 AND 2451100 GROUP BY i.i_category, i.i_brand, ws.ws_sold_date_sk ), returns_agg AS ( SELECT i.i_category, i.i_brand, ws.ws_sold_date_sk AS date_sk, SUM(wr.wr_return_amt_inc_tax) AS total_returns FROM web_returns wr JOIN web_sales ws ON wr.wr_order_number = ws.ws_order_number AND wr.wr_item_sk = ws.ws_item_sk JOIN item i ON i.i_item_sk = ws.ws_item_sk WHERE ws.ws_sold_date_sk BETWEEN 2450900 AND 2451100 GROUP BY i.i_category, i.i_brand, ws.ws_sold_date_sk ) SELECT COALESCE(sa.i_category, wa.i_category, ra.i_category) AS category, COALESCE(sa.i_brand, wa.i_brand, ra.i_brand) AS brand, COALESCE(sa.date_sk, wa.date_sk, ra.date_sk) AS date_sk, COALESCE(sa.store_sales_rev, 0) + COALESCE(wa.web_sales_rev, 0) AS total_sales_rev, COALESCE(sa.store_net_profit, 0) + COALESCE(wa.web_net_profit, 0) AS total_net_profit, COALESCE(ra.total_returns, 0) AS total_returns, (COALESCE(sa.store_net_profit, 0) + COALESCE(wa.web_net_profit, 0) - COALESCE(ra.total_returns, 0)) AS net_profit_after_returns, RANK() OVER (PARTITION BY COALESCE(sa.date_sk, wa.date_sk, ra.date_sk) ORDER BY (COALESCE(sa.store_net_profit, 0) + COALESCE(wa.web_net_profit, 0) - COALESCE(ra.total_returns, 0)) DESC) AS rank_by_net_profit FROM store_agg sa FULL OUTER JOIN web_agg wa ON sa.i_category = wa.i_category AND sa.i_brand = wa.i_brand AND sa.date_sk = wa.date_sk FULL OUTER JOIN returns_agg ra ON COALESCE(sa.i_category, wa.i_category) = ra.i_category AND COALESCE(sa.i_brand, wa.i_brand) = ra.i_brand AND COALESCE(sa.date_sk, wa.date_sk) = ra.date_sk ORDER BY net_profit_after_returns DESC LIMIT 100
